set -eu
Rscript - "$(inputs.input.path)" > metadata.tsv <<'RS'
args <- commandArgs(trailingOnly = TRUE)
p <- args[[1]]
x <- readRDS(p)
cat("input\t", basename(p), "\n", sep = "")
cat("class\t", paste(class(x), collapse = ","), "\n", sep = "")
md <- tryCatch(S4Vectors::metadata(x), error = function(e) NULL)
if (is.null(md)) {
  cat("metadata_error\tS4Vectors::metadata unavailable\n")
} else {
  cat("metadata_names\t", paste(names(md), collapse = ","), "\n", sep = "")
  for (nm in names(md)) {
    v <- md[[nm]]
    if (is.atomic(v) && length(v) <= 5) {
      cat("metadata.", nm, "\t", paste(as.character(v), collapse = ";"), "\n", sep = "")
    } else {
      cat("metadata.", nm, "\t<class=", paste(class(v), collapse = ","), ";length=", length(v), ">\n", sep = "")
    }
  }
}
